CREATE TABLE `expense_requirement_personnel` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  `test_order_no` varchar(100) NOT NULL COMMENT '试验单号',
  `supplier` varchar(50) DEFAULT NULL COMMENT '供应商',
  `outsourced_count` int NOT NULL DEFAULT '0' COMMENT '委外人数',
  `outsourced_personnel` longtext COMMENT '委外人员姓名（逗号分隔）',
  `responsible_person` varchar(50) DEFAULT NULL COMMENT '负责人',
  `end_date` date DEFAULT NULL COMMENT '试验结束日期（从飞书同步）',
  `requirement_date` date DEFAULT NULL COMMENT '发起试验需求日期',
  `start_date` date DEFAULT NULL COMMENT '试验开始日期（从飞书同步）',
  PRIMARY KEY (`id`),
  KEY `idx_expense_req_created_a77c19` (`created_at`),
  KEY `idx_expense_req_updated_a8660b` (`updated_at`),
  KEY `idx_expense_req_test_or_70168d` (`test_order_no`)
) ENGINE=InnoDB AUTO_INCREMENT=117 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='试验需求与人员关系';
